@@ -0,0 +1,204 @@
diff --git a/test/skills/cli_parity_test.dart b/test/skills/cli_parity_test.dart
@@ -86,6 +86,9 @@ const _nonSettingsCommands = <String, String>{

/// `/handoff` digest generation (gh-2102) — the core, host-agnostic half.
///
/// A handoff starts a FRESH session from an EDITABLE digest of the current
/// one: goal / work done / files / next steps, generated with the existing
/// branch-digest machinery ([generateBranchSummary] via [prepareBranchEntries]
/// and the shared [SummarizeFn] seam) but composed with a HANDOFF preamble —
/// the digest seeds a continuation session, it does not describe an abandoned
/// branch. The relevant-file list (files read / modified on the branch) rides
/// both the digest text (the `<read-files>`/`<modified-files>` tags the
/// branch summaries use) and the seeded record's `details`, so a resumed
/// session can re-surface the working set structurally.
///
/// Lossless guarantee: nothing here writes to the source session — the old
/// branch stays byte-identical and reachable (gh-2102 acceptance).
library;

import '../cancel_token.dart';
import '../session/session_record.dart';
import '../session/session_tree.dart';
import 'branch_summarization.dart';
import 'compaction.dart';

export 'branch_summarization.dart' show branchSummaryPrompt;

/// Fixed preamble composed into a handoff digest: the text is a checkpoint
/// of the PREVIOUS session seeding a continuation (not an abandoned branch —
/// that distinction is why this is not [branchSummaryPreamble]).
const String handoffDigestPreamble =
    'This session continues earlier work from a previous conversation '
    '(handed off by the user). Checkpoint of that earlier session:';

/// `customType` of the seeded handoff record on the fresh session
/// (`CustomMessageRecord`, projects into model context as a user message).
const String handoffDigestCustomType = 'handoff_digest';

/// Outcome of [generateHandoffDigest]: success carries [summary] — the
/// editable digest text, [handoffDigestPreamble] and the file-operation tags
/// included — plus the relevant-file lists; failure carries [error] (or
/// [aborted]) instead of throwing.
final class HandoffDigestResult {
  /// Creates a [HandoffDigestResult].
  const HandoffDigestResult({
    this.summary,
    this.readFiles = const [],
    this.modifiedFiles = const [],
    this.aborted = false,
    this.error,
  });

  /// The generated digest (`null` when generation failed or was aborted).
  final String? summary;

  /// Files read on the handed-off branch, sorted (modified files excluded).
  final List<String> readFiles;

  /// Files modified on the handed-off branch, sorted.
  final List<String> modifiedFiles;

  /// Whether the digest call was aborted rather than failed.
  final bool aborted;

  /// The failure description when generation failed.
  final String? error;

  /// Whether a digest was produced.
  bool get isSuccess => summary != null;
}

/// Collect every entry of [session]'s CURRENT branch (leaf → root,
/// chronological) for the digest — the branch-digest walk without a tree
/// move: the whole conversation is what a handoff carries over.
Future<List<SessionRecord>> collectEntriesForHandoff(Session session) async {
  final leafId = await session.getLeafId();
  if (leafId == null) return const [];
  return session.getBranch(fromId: leafId);
}

/// Generate a handoff digest from [entries] (the current branch, per
/// [collectEntriesForHandoff]) — the branch-digest generation with the
/// handoff preamble. Never throws: failures surface on the result.
///
/// LOSSLESS: nothing is appended to any session; the digest lives only on
/// the returned result until the host seeds the continuation session.
Future<HandoffDigestResult> generateHandoffDigest(
  List<SessionRecord> entries, {
  required SummarizeFn summarize,
  int tokenBudget = 0,
  CancelToken? cancelToken,
}) async {
  if (entries.isEmpty) {
    return const HandoffDigestResult(error: 'nothing to summarize');
  }
  // Records without conversation content (labels, session metadata, empty
  // branch summaries) would come back as the branch generator's
  // 'No content to summarize' placeholder — a handoff must never seed a
  // fresh session with that placeholder dressed up as a digest.
  if (prepareBranchEntries(
    entries,
    tokenBudget: tokenBudget,
  ).messages.isEmpty) {
    return const HandoffDigestResult(error: 'no content to summarize');
  }
  final result = await generateBranchSummary(
    entries,
    summarize: summarize,
    tokenBudget: tokenBudget,
    cancelToken: cancelToken,
    preamble: handoffDigestPreamble,
  );
  if (result.aborted) return const HandoffDigestResult(aborted: true);
  if (result.summary == null) {
    return HandoffDigestResult(error: result.error ?? 'digest failed');
  }
  return HandoffDigestResult(
    summary: result.summary,
    readFiles: result.readFiles ?? const [],
    modifiedFiles: result.modifiedFiles ?? const [],
  );
}

/// Seed [session] (the FRESH continuation session) with the digest: one
/// `handoff_digest` custom-message record — content is the digest text
/// (projects into model context as a user message, [CustomMessageRecord.display]
/// keeps it visible in the transcript), `details` carries the relevant-file
/// lists for structural re-surfacing. Returns the new record id.
Future<String> seedHandoffRecord(
  Session session, {
  required String digest,
  List<String> readFiles = const [],
  List<String> modifiedFiles = const [],
}) {
  return session.appendCustomMessageEntry(
    customType: handoffDigestCustomType,
    content: digest,
    display: true,
    details: {'readFiles': readFiles, 'modifiedFiles': modifiedFiles},
  );
}

part of 'agent_cli.dart';

// `/handoff` (gh-2102): start a FRESH session from an EDITABLE digest of the
// current one. The digest reuses the branch-digest generation
// (`handoff_digest.dart` — prepareBranchEntries + the shared summarizer
// seam) composed with a handoff preamble; the user edits it in their
// `$EDITOR`; the fresh session is seeded with the edited digest + the
// relevant-file list. The OLD session is never written to: nothing is
// deleted, the branch stays reachable (the lossless guarantee) — the
// receipt prints its resume link.

/// The `/handoff` scratch digest file name marker (the editor simulator in
/// tests keys off it; the file lives under `<cwd>/.fah/` and is removed
/// after the flow).
const _handoffDigestFilePattern = 'handoff-digest';

/// Composes the external-editor invocation for the digest file:
/// `<editor> '<path>'` with POSIX single-quote escaping of the path.
String handoffEditorCommand(String editor, String path) =>
    "$editor '${path.replaceAll("'", r"'\''")}'";

/// `/handoff` (gh-2102) — the edit-then-start flow.
extension HandoffSlashCommand on AgentCli {
  Future<void> _handoffSlash(String rest) async {
    final session = _session;
    if (session == null) return;
    // Never switch sessions under a streaming turn (the /update settle
    // contract): the digest call itself is the only wait after this.
    await _settled;
    // The SESSION branch is the authority — not `_agent.state.messages`,
    // which a resumed session only rebuilds at its first drive.
    final entries = await collectEntriesForHandoff(session);
    if (entries.isEmpty) {
      io.writeln('nothing to hand off — this session has no conversation');
      return;
    }

    // 1. Generate the digest (branch-digest machinery, handoff preamble).
    _pushBusyPhase('Writing handoff digest…');
    _waiting.compactionLivenessStart();
    final HandoffDigestResult digest;
    try {
      final slot = _resolveMemoryLlmSlot();
      if (slot == null) {
        io.writeln('handoff digest failed: no summarizer model available');
        return;
      }
      digest = await generateHandoffDigest(
        entries,
        summarize: streamFunctionSummarizer(slot.stream, slot.model),
      );
    } finally {
      _waiting.compactionLivenessEnd();
      _pushBusyPhase('');
    }
    if (digest.aborted) {
      io.writeln(_style.dim('handoff interrupted'));
      return;
    }
    if (digest.summary == null) {
      io.writeln('handoff digest failed: ${digest.error}');
      return;
    }

    // 2. Open it for editing.
    final edited = await _editHandoffDigest(digest.summary!);
    if (edited == null) return; // cancelled — the flow already reported

    // 3. Start the fresh session seeded with digest + file list.
    await _switchToHandoffSession(
      digest: edited,
      readFiles: digest.readFiles,
      modifiedFiles: digest.modifiedFiles,
    );
  }

  /// Writes [digest] to a scratch file, opens it in the user's editor, and
  /// returns the edited text. Returns `null` only when the handoff is
  /// CANCELLED (the file was emptied). Every unavailable-edit path degrades
  /// to the generated digest with a visible note — the LM call is already
  /// paid for; an unusable editor must not waste it.
  Future<String?> _editHandoffDigest(String digest) async {
    final dir = (await _env.joinPath([_env.cwd, '.fah'])).valueOrNull;
    if (dir == null) return digest;
    await _env.createDir(dir, recursive: true);
    final path = (await _env.joinPath([
      dir,
      '$_handoffDigestFilePattern-${DateTime.now().millisecondsSinceEpoch}.md',
    ])).valueOrNull;
    if (path == null) return digest;
    final editor = _resolveHandoffEditor();
    try {
      if ((await _env.writeFile(path, digest)).isErr) {
        io.writeln(
          _style.dim(
            'handoff: could not write the digest file — using it as '
            'generated',
          ),
        );
        return digest;
      }
      if (editor == null || !io.isInteractive) {
        io.writeln(
          _style.dim(
            'no editor configured — using the digest as generated '
            '(set FA_EDITOR, VISUAL or EDITOR to edit before the handoff)',
          ),
        );
        return digest;
      }
      final run = await _env.exec(handoffEditorCommand(editor, path));
      final exit = run.valueOrNull?.exitCode;
      if (run.isErr || (exit != null && exit != 0)) {
        io.writeln(
          _style.dim(
            'editor exited (${run.errorOrNull?.message ?? 'exit $exit'}) — '
            'using the digest as generated',
          ),
        );
        return digest;
      }
      final readBack = await _env.readTextFile(path);
      final text = readBack.valueOrNull;
      if (text == null) {
        io.writeln(
          _style.dim(
            'handoff: could not read back the edited digest — using it as '
            'generated',
          ),
        );
        return digest;
      }
      if (text.trim().isEmpty) {
        // Emptying the file is the cancel gesture: no session switch.
        io.writeln('handoff cancelled — the digest was emptied');
        return null;
      }
      return text;
    } finally {
      // Best-effort scratch cleanup — never blocks or fails the flow.
      unawaited(_env.remove(path, force: true));
    }
  }

  /// The external editor for the digest: `FA_EDITOR` > `VISUAL` > `EDITOR`;
  /// null when the host wired no env lookup or none is set.
  String? _resolveHandoffEditor() {
    final lookup = config.envVarValue;
    if (lookup == null) return null;
    for (final name in const ['FA_EDITOR', 'VISUAL', 'EDITOR']) {
      final value = lookup(name);
      if (value != null && value.trim().isNotEmpty) return value.trim();
    }
    return null;
  }

  /// The switch itself: mirrors `/reset`'s in-process session switch, seeds
  /// the fresh session with the digest record, and injects the digest as
  /// the live opening context (counted as persisted — its durable form is
  /// the `handoff_digest` record, so the next run never re-persists it as
  /// a plain message; the TTSR-injection pattern).
  Future<void> _switchToHandoffSession({
    required String digest,
    required List<String> readFiles,
    required List<String> modifiedFiles,
  }) async {
    _agent.reset();
    _checkpoints.clear();
    _ttsr?.reset();
    // The image-drop latch is run-lifetime state (issue #1889 R4): a
    // brand-new session re-latches from its first request.
    imageDropUx.reset();
    final previousSession = _session;
    final fresh = await _createSession();
    await seedHandoffRecord(
      fresh,
      digest: digest,
      readFiles: readFiles,
      modifiedFiles: modifiedFiles,
    );
    _agent.state.messages = [UserMessage.text(digest)];
    _session = fresh;
    _notifyPluginSessionReady();
    // herdr must re-report the switch (#1483 review) and the fabric
    // mailboxes follow the new session.
    _herdrSessionSwitched();
    _syncMailboxPrefix();
    // Re-claim ownership for the new session (#428).
    await _reclaimAfterSwitch(previousSession);
    await _printViewerBannerIfAny();
    _persistedCount = 1;
    io.writeln('handed off to a fresh session');
    // Cross-session link back: the old session is untouched and reachable.
    var oldRef = (await previousSession?.getMetadata())?.id;
    final oldName = await previousSession?.getSessionName();
    if (oldName != null && oldName.isNotEmpty) oldRef = oldName;
    io.writeln(
      _style.dim(
        "the previous session is byte-identical and stays reachable: "
        "fa --session '$oldRef'",
      ),
    );
  }
}

  return name;
}

/// Pages older chunks into a windowed storage until the newest
/// compaction record is resident — the "open from the end, up to the
/// compaction" resume (owner directive): a marathon session opens in
/// O(tail-after-compaction) instead of parsing gigabytes. Stops when
/// the active branch carries a [CompactionRecord], when [tokenBudget]
/// is already covered by the resident tail, or when the file start is
/// reached (sessions without compaction page everything, as before).
/// A no-op for full storages. [maxPages] bounds pathological files.
///
/// The walk keeps the TAIL ANCHORED (WindowedSessionStorage.
/// growOlderUntil suspends the residency eviction): the previous
/// loadOlder-based loop slid the newest side out on the first chunk —
/// the branch read empty and every deep-boundary resume fell back to
/// a full open (10s+ on a 1.4 GB live session). Returns false only on
/// [maxPages] exhaustion — the caller's documented full-open fallback;
/// a genuinely empty session reports `true`.
///
/// [tokenBudget] (issue #503) stops the walk as soon as the resident
/// tail's estimated context tokens cover the model's window — a resume
/// needs only what fits the context, and older history pages in lazily
/// through the scrollback's loadOlder path. `null` walks to the
/// boundary/file head as before.
Future<bool> ensureCompactionBoundaryResident({
  int maxPages = 512,
  int? tokenBudget,
}) async {
  final storage = _storage;
  if (storage is! WindowedSessionStorage) return true;
  return storage.growOlderUntil(
    (r) => r is CompactionRecord,
    maxPages: maxPages,
    tokenBudget: tokenBudget,
  );
}

/// Pages older blocks until a record that projects into conversation
/// context is resident. Registry-only live tails (subagent/shell custom
/// records) otherwise make a windowed open look like an empty chat even
/// though messages exist immediately above the tail. The walk keeps the
/// newest side anchored and is bounded by [maxPages]; full storages are a
/// no-op. Returns false only when that page bound is exhausted.
Future<bool> ensureConversationResident({int maxPages = 16}) async {
  final storage = _storage;
  if (storage is! WindowedSessionStorage) return true;
  return storage.growOlderUntil(
    (record) =>
        record is MessageRecord ||
        record is CustomMessageRecord ||
        record is CompactionRecord ||
        (record is BranchSummaryRecord && record.summary.isNotEmpty),
    maxPages: maxPages,
  );
}

