final class _FailingEditorEnv extends ForwardingFs
    with ForwardingRangedReadFs, ForwardingRenamableFs {
  _FailingEditorEnv(super.delegate);

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
