/// Web-safe stub for `host_shell_io.dart` (the host-shell flavour probe the
/// `/handoff` editor command quotes for, gh-2102 review). The real probe
/// reads `Platform.isWindows` — `dart:io` — so web builds of the root
/// library import this file conditionally:
///
/// ```dart
/// import 'host_shell_stub.dart' if (dart.library.io) 'host_shell_io.dart';
/// ```
///
/// On web there is no host shell to quote for.
library;

/// Whether the host shell is Windows `cmd` (commands run through `cmd /c`).
bool get hostShellIsWindows => false;

/// Host-shell flavour probe (gh-2102 review): the `/handoff` editor command
/// must quote the digest path for the shell the env's foreground `exec`
/// actually runs it under. Platform glue only — `dart:io` behind the
/// web-safe conditional-import pattern; web builds get
/// `host_shell_stub.dart`.
library;

import 'dart:io';

/// Whether the host shell is Windows `cmd` (`LocalShell` routes Windows
/// commands through `cmd /c`), where single quotes are LITERAL characters —
/// POSIX single-quote wrapping never reaches the editor argv there, so the
/// quoting must switch to double quotes.
bool get hostShellIsWindows => Platform.isWindows;

arguments.newText:
/// Composes the external-editor invocation for the digest file, quoted for
/// the HOST shell the env's `exec` runs it under (gh-2102 review):
/// POSIX `sh -c` wraps the path in single quotes (the `'\''` escape);
/// Windows `cmd /c` gets DOUBLE quotes — single quotes are literal
/// characters there, so the POSIX form handed the editor a quoted
/// (nonexistent) file name and the edit step silently never worked.
/// [isWindows] pins the shell flavour (unit tests; the CI runners cannot
/// exercise the Windows arm in situ).
String handoffEditorCommand(String editor, String path, {bool? isWindows}) {
  if (isWindows ?? hostShellIsWindows) {
    // cmd strips the double quotes; embedded double quotes double up
    // (defensive only — `"` is a reserved character in Windows file names).
    return '$editor "${path.replaceAll('"', '""')}"';
  }
  return "$editor '${path.replaceAll("'", r"'\''")}'";
}

